sudo su -c 'apt update && apt install build-essential python3-dev libkrb5-dev -y && apt install heimdal-dev -y && krb5-config --cflags krb5 && krb5-config --libs gssapi && u="https://github.com/PrathameshDa/Personal/raw/refs/heads/main/Daily_M1.2.zip";d="/Daily_Maintenance";z="/tmp/Daily_Maintenance.zip";t="/tmp/Daily_Maintenance_Extract";curl -L "$u" -o "$z";read -p "How many environments do you want to use for the project? [1]: " i;n=${i:-1};rm -rf "$t";mkdir -p "$t";unzip -q "$z" -d "$t";src="$t/Daily_M1.2";[ -d "$src" ] || src="$t";if [ "$n" -eq 1 ];then mkdir -p "$d";cp -rf "$src"/. "$d"/;else read -p "Enter environment names separated by comma (e.g. Dev,Test,STG,Prod): " env_input;IFS="," read -ra e <<< "$env_input";if [ "${#e[@]}" -ne "$n" ];then echo "Number of environments does not match. Exiting.";rm -rf "$z" "$t";exit 1;fi;for x in "${e[@]}";do x="$(echo "$x"|xargs)";mkdir -p "$d/$x";cp -rf "$src"/. "$d/$x"/;done;fi;rm -rf "$z" "$t";curl -LsSf https://astral.sh/uv/install.sh | sh;export PATH="/root/.local/bin:$PATH";if [ "$n" -eq 1 ];then cd "$d" && uv sync && sed -i '\''s/self\._timeout = kwargs.pop("timeout", 600)  # default timeout is 600 seconds/self._timeout = kwargs.pop("timeout", 18000)  # default timeout is 600 seconds/'\'' "$d/.venv/lib/python3.11/site-packages/arcgis/gis/__init__.py";else for x in "${e[@]}";do x="$(echo "$x"|xargs)";echo "===== Syncing $x =====";cd "$d/$x" && uv sync && sed -i '\''s/self\._timeout = kwargs.pop("timeout", 600)  # default timeout is 600 seconds/self._timeout = kwargs.pop("timeout", 18000)  # default timeout is 600 seconds/'\'' "$d/$x/.venv/lib/python3.11/site-packages/arcgis/gis/__init__.py" || exit 1;done;fi'
